    <div class="stats" id="stats">
        共 <strong id="imageCount">0</strong> 张图片 · 点击刷新
        <button onclick="location.reload()" style="
        background: none;
        border: none;
        color: #7c3aed;
        cursor: pointer;
        font-size: 14px;
        text-decoration: underline;
        padding: 0 4px;
      ">⟳ 重新加载</button>
    </div>

    <script>
        // ============================================================
        //  1. 图片数据：使用 picsum.photos 生成不同尺寸的真实图片
        //     每张图片固定宽度 600px，高度在 400~900px 之间随机
        //     这样宽高比不同，瀑布流效果更明显
        // ============================================================
        const IMAGE_COUNT = 24; // 图片数量

        // 生成图片数据
        function generateImages(count) {
            const images = [];
            const seeds = [
                'forest', 'ocean', 'mountain', 'city', 'desert',
                'lake', 'flower', 'cloud', 'sunset', 'aurora',
                'river', 'stone', 'tree', 'wind', 'rain',
                'snow', 'star', 'moon', 'bird', 'fish',
                'leaf', 'fire', 'ice', 'wave'
            ];
            for (let i = 0; i < count; i++) {
                const seed = seeds[i % seeds.length] + '-' + (i + 1);
                // 随机高度 400~900，步长 10
                const height = Math.floor(Math.random() * 50 + 40) * 10;
                // 固定宽度 600
                const width = 600;
                // 使用 picsum.photos 的 seed 模式，保证每次刷新图片一致
                const src = `https://picsum.photos/seed/${seed}/${width}/${height}`;
                // 同时记录原始宽高，用于计算比例
                images.push({
                    src: src,
                    width: width,
                    height: height,
                    alt: `图片 ${i + 1}`,
                    // 给一些图片添加不同的背景色（备用）
                    bg: `hsl(${(i * 37) % 360}, 70%, 92%)`
                });
            }
            return images;
        }

        // ============================================================
        //  2. 瀑布流布局算法（核心）
        //     使用 CSS Grid 的 grid-column 和 grid-row 精确定位
        //     算法：每次将图片放入当前高度最小的列
        // ============================================================
        function layoutMasonry(grid, items) {
            // --- 配置 ---
            const colCount = 3; // 列数（与 CSS 中的 grid-template-columns 一致）
            const baseRow = 10; // 基准行高（px），必须与 CSS 的 grid-auto-rows 一致
            const gap = 16; // 间距（px），必须与 CSS 的 gap 一致

            // 获取 grid 容器的实际内容宽度
            const gridStyle = getComputedStyle(grid);
            const gridWidth = grid.clientWidth -
                parseFloat(gridStyle.paddingLeft) -
                parseFloat(gridStyle.paddingRight);

            // 计算列宽（考虑间距）
            const colWidth = (gridWidth - gap * (colCount - 1)) / colCount;

            // --- 初始化每列的当前高度（px）和当前行号 ---
            const colHeights = new Array(colCount).fill(0);
            const colRows = new Array(colCount).fill(0);

            // --- 遍历每个 item 进行布局 ---
            items.forEach((item, index) => {
                const img = item.querySelector('img');
                // 获取图片原始宽高（可能尚未加载完成，用 data 属性暂存）
                let naturalW = img.naturalWidth || parseInt(img.getAttribute('data-width')) || 600;
                let naturalH = img.naturalHeight || parseInt(img.getAttribute('data-height')) || 400;

                // 如果图片还没加载完，先用 data 属性
                if (!img.naturalWidth) {
                    naturalW = parseInt(img.getAttribute('data-width')) || 600;
                    naturalH = parseInt(img.getAttribute('data-height')) || 400;
                }

                // 计算图片在 grid 中实际显示的高度（等比例缩放）
                const aspectRatio = naturalW / naturalH;
                const itemHeight = colWidth / aspectRatio;

                // 计算需要占据的 grid 行数（向上取整 + 1 保证不重叠）
                const spanRows = Math.ceil(itemHeight / baseRow) + 1;

                // --- 找到当前最矮的列 ---
                let minCol = 0;
                let minHeight = colHeights[0];
                for (let j = 1; j < colCount; j++) {
                    if (colHeights[j] < minHeight) {
                        minHeight = colHeights[j];
                        minCol = j;
                    }
                }

                // 计算当前列的起始行号（从 1 开始）
                const startRow = Math.floor(colRows[minCol]) + 1;
                const endRow = startRow + spanRows;

                // --- 设置 grid 位置 ---
                item.style.gridColumn = `${minCol + 1}`;
                item.style.gridRow = `${startRow} / ${endRow}`;

                // --- 更新列高度和行号 ---
                // 高度增加：图片高度 + 间距
                colHeights[minCol] += itemHeight + gap;
                colRows[minCol] = endRow;
            });

            // 返回总高度（用于调试）
            return Math.max(...colHeights);
        }

        // ============================================================
        //  3. 渲染瀑布流
        // ============================================================
        async function renderMasonry() {
            const grid = document.getElementById('masonryGrid');
            const loadingTip = document.getElementById('loadingTip');
            const countEl = document.getElementById('imageCount');

            // 清空容器（保留 loadingTip）
            grid.innerHTML = '';
            grid.appendChild(loadingTip);
            loadingTip.style.display = 'block';

            // 生成图片数据
            const images = generateImages(IMAGE_COUNT);

            // 创建所有 grid-item 但先不插入
            const fragment = document.createDocumentFragment();
            const items = [];

            images.forEach((imgData, idx) => {
                const item = document.createElement('div');
                item.className = 'grid-item';

                // 内部包裹（可选，为了更好的样式控制）
                const inner = document.createElement('div');
                inner.className = 'grid-item-inner';
                inner.style.backgroundColor = imgData.bg;

                const img = document.createElement('img');
                img.src = imgData.src;
                img.alt = imgData.alt;
                // 存储原始宽高，以便在布局时使用
                img.setAttribute('data-width', imgData.width);
                img.setAttribute('data-height', imgData.height);
                img.setAttribute('data-loaded', 'false');
                img.loading = 'lazy';

                // 图片加载完成后更新标记
                img.onload = () => {
                    img.setAttribute('data-loaded', 'true');
                };
                // 如果图片缓存已加载，立即标记
                if (img.complete && img.naturalWidth) {
                    img.setAttribute('data-loaded', 'true');
                }

                inner.appendChild(img);
                item.appendChild(inner);
                fragment.appendChild(item);
                items.push(item);
            });

            // 移除 loading 提示
            loadingTip.style.display = 'none';

            // 将所有 item 添加到 grid
            grid.appendChild(fragment);

            // --- 等待所有图片加载完成后再布局 ---
            const allImages = grid.querySelectorAll('img');
            const loadPromises = Array.from(allImages).map(img => {
                if (img.complete && img.naturalWidth) {
                    return Promise.resolve();
                }
                return new Promise((resolve) => {
                    img.onload = resolve;
                    img.onerror = resolve; // 加载失败也继续
                });
            });

            // 显示加载状态
            loadingTip.style.display = 'block';
            loadingTip.innerHTML = `
            <div class="spinner"></div>
            <p>正在排列瀑布流…</p>
          `;
            grid.appendChild(loadingTip);

            // 等待所有图片加载完成（或至少大部分）
            await Promise.all(loadPromises);

            // 隐藏加载提示
            loadingTip.style.display = 'none';

            // --- 执行瀑布流布局 ---
            layoutMasonry(grid, items);

            // --- 更新统计 ---
            countEl.textContent = images.length;

            // --- 处理窗口缩放：重新布局（防抖） ---
            let resizeTimer = null;
            const handleResize = () => {
                if (resizeTimer) clearTimeout(resizeTimer);
                resizeTimer = setTimeout(() => {
                    // 重新计算布局
                    layoutMasonry(grid, items);
                }, 200);
            };
            window.addEventListener('resize', handleResize);

            // 返回清理函数（用于组件卸载）
            return () => {
                window.removeEventListener('resize', handleResize);
            };
        }

        // ============================================================
        //  4. 启动
        // ============================================================
        document.addEventListener('DOMContentLoaded', () => {
            renderMasonry().catch(console.error);
        });
    </script>

</body>
</html>
